import sys; sys.path.insert(0,'.')
from gen import *
IMP='כלמוביל'
ML='https://www.manualslib.com/manual/{}/x.html?page={}'
s=S('mitsubishi-l200-2006-2015-2.5-diesel','Mitsubishi','מיצובישי','L200','L200 (טריטון)','KB/KA (דור 4)',(2006,2015),['2.5 DI-D (4D56)'],'diesel',IMP,10000,12,
    'לפי טבלת "General Export" של מיצובישי לפלטפורמה זו: שמן ומסנן שמן בדיזל כל 10,000 ק"מ או 12 חודשים (בתנאים קשים כל 5,000); שאר הבדיקות כל 20,000 ק"מ או 12 חודשים',120000)
s.every('engine_oil','replace',10000); s.every('oil_filter','replace',10000)
for k in s.kms():
    for it,n in (('brake_fluid','בדיקת מפלס נוזל בלמים ומצמד'),('battery_12v',None),('pedals','חופש דוושות בלם ומצמד')): s.add(k,it,'inspect',n)
