s.every('air_filter','inspect',20000,'בתנאי אבק כל 10,000 ק"מ או 6 חודשים')
s.every('air_filter','replace',40000)
s.every('brake_fluid','replace',40000,'כל 40,000 ק"מ או שנתיים')
s.every('fuel_filter','replace',20000,'מסנן סולר כל 20,000 ק"מ או 12 חודשים')
for it in ('suspension','propshaft','cv_boots','steering','manual_gearbox_oil','transfer_case_oil','differential_oil','exhaust','parking_brake','wheel_alignment','brake_lines','brake_pads','brake_discs','transmission_oil','diagnostics'):
    note={'propshaft':'גירוז גל ההינע','manual_gearbox_oil':'בדיקת דליפות','transfer_case_oil':'בדיקת דליפות','differential_oil':'בדיקת דליפות בדיפרנציאל קדמי ואחורי','transmission_oil':'בדיקת מפלס בגיר אוטומטי','diagnostics':'בדיקת סל"ד סרק, מערכת EGR ולימוד כמות הזרקה במערכת Common Rail; נסיעת מבחן','cv_boots':'בתנאים קשים כל 10,000'}.get(it)
    s.every(it,'inspect',20000,note)
s.add(60000,'suspension','inspect','בדיקת מרווח מיסבי גלגלים (כל 60,000 ק"מ או 3 שנים)'); s.add(120000,'suspension','inspect','בדיקת מרווח מיסבי גלגלים')
s.every('brake_drums','inspect',40000,'בלמי תוף (אם קיימים); בתנאים קשים כל 10,000')
s.every('fuel_lines','inspect',40000)
s.li('timing_belt','replace',every_km=100000,note='כולל רצועת איזון (B) במנוע 4D56')
s.li('manual_gearbox_oil','replace',every_km=100000,note='בתנאים קשים כל 40,000')
s.li('transfer_case_oil','replace',every_km=100000,note='בתנאים קשים כל 40,000')
s.li('differential_oil','replace',every_km=80000,note='דיפרנציאל רגיל; בתנאים קשים כל 40,000. בדיפרנציאל LSD היברידי כל 40,000 (קשים: 20,000)')
s.li('transmission_oil','replace',every_km=40000,note='גיר אוטומטי: בטבלת General Export מופיעה החלפה רק בתנאים קשים (כל 40,000)')
s.li('cabin_filter','replace',every_km=15000,every_months=12,note='מסנן מטהר אוויר בתא הנוסעים')
