s.src(ML.format(1634870,31),'manufacturer','Mitsubishi Pajero Sport 2013 (KH, אותה פלטפורמה ואותו מנוע 4D56 כמו L200/Triton) Inspection and Maintenance manual, "Periodic Inspection and Maintenance Schedule - For General Export" (manualslib עמ\' 31-34); טבלת "For Europe" בעמ\' 34-37')
s.src('https://www.mitsubishi-motors.com.au/owners/service/maintenance-schedule.html','manufacturer','מיצובישי אוסטרליה מפרסמת לוחות רק לדגמים מ-2015 ואילך (Triton MQ/MR); לדור KB/MN אין לוח')
s.write('draft','טיוטה: לא נמצא לוח ישראלי ל-L200 דור 4. הלוח נבנה מטבלת "General Export" במדריך הבדיקה והתחזוקה של פג\'רו ספורט 2013, שבנוי על אותה פלטפורמה ואותו מנוע 2.5 דיזל 4D56 כמו ה-L200/טריטון. רצועת תזמון (כולל רצועת איזון) כל 100,000 ק"מ, מסנן סולר כל 20,000, נוזל קירור ונוזל בלמים כל 40,000 או שנתיים. בטבלה האירופית של אותו מסמך הטיפול הוא כל 20,000 ק"מ, ונוזל הקירור כל 60,000 או 4 שנים. הספר מגדיר נהיגה בעומס תנועה בחום מעל 32 מעלות, אבק ודרכים משובשות כתנאים קשים.')
rule('Mitsubishi',['L200','L 200','L-200'],(2006,2015),'mitsubishi-l200-2006-2015-2.5-diesel',engine_codes=['4D56'])
